const __t = ($input.first().json.query || {}).token;
if (__t !== '8j1bXp92BF5VabxNq2VN') return [{ json: { error: 'forbidden' } }];
// Нода подключена напрямую к Webhook в той же workflow, что и Schedule Trigger-ветка.
// Static Data общая на весь workflow, поэтому здесь доступны данные,
// записанные веткой с Schedule Trigger.

const staticData = $getWorkflowStaticData('global');
const cached = staticData.weeklyNutrients;

if (!cached) {
  // Кэш ещё ни разу не считался (например, сразу после создания workflow) —
  // отдаём понятную заглушку вместо ошибки.
  return [{
    json: {
      error: 'no_data_yet',
      message: 'Данные ещё не посчитаны. Дождитесь первого запуска по расписанию.'
    }
  }];
}

return [{ json: cached }];

// Нода подключена к прямому выходу "Get Meals" (последняя в цепочке Schedule Trigger).
// Ссылается на "Get day_sum" и "Get Nutrient_Targets" по имени — обе идут раньше в цепочке:
// Schedule Trigger → Get day_sum → Get Nutrient_Targets → Get Meals → Code

// Достаёт первое число из строки-ячейки. Возвращает null, если значение
// начинается с "не " (не установлен / не применимо / не задана) — иначе
// регэксп нашёл бы случайное число из справочного текста в скобках.
function parseNum(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  if (/^не\s/i.test(s)) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  if (!m) return null;
  return parseFloat(m[0].replace(',', '.'));
}

function toNum(v) {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

// 1. Дни за неделю — обращаемся к "Get day_sum" по имени.
// ВАЖНО: в отличие от wellness-домена (Daily_Trends, колонка 'Дата', кириллица),
// у day_sum дата хранится в колонке 'Date' (латиница) — известная особенность проекта.
const dayRows = $('Get day_sum').all()
  .map(r => r.json)
  .filter(r => r['Date'])
  .sort((a, b) => (a['Date'] < b['Date']) ? 1 : (a['Date'] > b['Date']) ? -1 : 0)
  .slice(0, 7)
  .reverse(); // от старых к новым

const weekDateSet = new Set(dayRows.map(r => r['Date'].slice(0, 10))); // YYYY-MM-DD

// 2. Справочник целей — обращаемся к "Get Nutrient_Targets" по имени
const targets = $('Get Nutrient_Targets').all().map(r => r.json);

// 3. Сырые приёмы пищи за ту же неделю — прямой вход этой ноды (Get Meals)
const weekMeals = $input.all()
  .map(r => r.json)
  .filter(r => r['Date'] && weekDateSet.has(String(r['Date']).slice(0, 10)));

// Топ-3 продукта-источника нутриента ЗА КОНКРЕТНЫЙ ДЕНЬ (не за неделю), сгруппированные
// по описанию блюда. % считается от ДНЕВНОЙ нормы/лимита — так сумма топ-3 напрямую
// объясняет цифру в самой ячейке heatmap за этот день, а не абстрактную "долю от недели".
function topSourcesForDay(col, dateStr, dailyTarget) {
  if (!dailyTarget) return [];
  const dayMeals = weekMeals.filter(m => String(m['Date']).slice(0, 10) === dateStr);
  const byName = {};
  dayMeals.forEach(m => {
    const v = toNum(m[col]);
    if (v <= 0) return;
    const name = m['Meal_description'] || 'Без описания';
    byName[name] = (byName[name] || 0) + v;
  });
  return Object.entries(byName)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([name, val]) => ({ name, pct: Math.round((val / dailyTarget) * 100) }));
}

const HEAT_METRICS = [];
const NORMAL_METRICS = [];
const CATEGORY_SCORES = {}; // { "Здоровье костей": [pct, pct, ...] }
const CATEGORY_DETAILS = {}; // { "Здоровье костей": [{label, pct}, ...] } — для карточек с разбивкой
const BULLETS = [];
const SOURCES = {}; // { "Витамин D": [{name, pct}, ...] }

targets.forEach(t => {
  const col = t['Колонка_в_Meals'];
  if (!col) return;

  const rda = parseNum(t['Норма_RDA_AI']);
  const ul = parseNum(t['Верхний_предел_UL']);
  const categories = (t['Категория'] || '').split(';').map(c => c.trim()).filter(Boolean);
  const isLimitType = categories.includes('Риск избытка');

  // UL некоторых нутриентов (магний и т.п.) относится ТОЛЬКО к добавкам, не к пище —
  // см. поле Примечание в справочнике. Такой UL не применяем к дневному рациону.
  const ulAppliesToDiet = !/добав/i.test(String(t['Верхний_предел_UL'] || ''));

  const dailyValues = dayRows.map(r => toNum(r[col]));
  const dailyPct = dailyValues.map(v => {
    if (isLimitType) return ul ? Math.round((v / ul) * 100) : null;
    return rda ? Math.round((v / rda) * 100) : null;
  }).filter(p => p !== null);

  if (dailyPct.length === 0) return; // нет ни цели, ни UL — пропускаем

  const avgPct = Math.round(dailyPct.reduce((a, b) => a + b, 0) / dailyPct.length);

  // Показываем в heatmap только ГЕНУИННЫЕ недельные паттерны, не разовые всплески дня:
  // - дефицит — если недельное СРЕДНЕЕ ниже нормы (не просто один плохой день)
  // - избыток — только для goal-type нутриентов (магний, витамин D и т.п.), и только если
  //   минимум 2 дня подряд/за неделю реально вышли за порог (один разовый приём — не система)
  // Risk-type нутриенты (натрий, сахар и т.п.) в heatmap не попадают вообще — они и так
  // всегда видны в "Риск избытка", дублировать их здесь — просто шум.
  const upperBoundPct = (ul && rda) ? Math.round((ul / rda) * 100) : null;
  const daysOverThreshold = (upperBoundPct && ulAppliesToDiet)
    ? dailyPct.filter(p => p > upperBoundPct).length
    : 0;
  const deviates = !isLimitType && (avgPct < 85 || daysOverThreshold >= 2);

  // --- Фаза 6: абсолютные величины, расстояние до верхнего предела, уровень сигнала ---
  // Процент без базы и единиц не интерпретируем, поэтому отдаём и абсолюты, и UL.
  const avgAbs = dailyValues.length
    ? Math.round((dailyValues.reduce((a, b) => a + b, 0) / dailyValues.length) * 100) / 100
    : null;
  const ulEffective = (ul && ulAppliesToDiet) ? ul : null;
  const ulRatio = (ulEffective && avgAbs != null && ulEffective > 0) ? avgAbs / ulEffective : null;
  const ulRatioR = ulRatio != null ? Math.round(ulRatio * 100) / 100 : null;
  const ulNote = (ul && !ulAppliesToDiet) ? 'верхний предел относится только к добавкам, не к пище' : null;
  const daysBelow = dailyPct.filter(p => p < 85).length;

  // Лестница сигналов: 0 норма · 1 дефицит · 2 устойчивый дефицит · 3 подход к пределу · 4 выше предела
  // Важно: дефицит определяется по НЕДЕЛЬНОМУ среднему. Отдельные «плохие» дни есть
  // у любого нутриента (обычные колебания) и сами по себе сигналом не являются —
  // они лишь усиливают уже подтверждённый средним дефицит до «устойчивого».
  const lastDayPct = dailyPct.length ? dailyPct[dailyPct.length - 1] : null;
  let level = 0;
  if (isLimitType) {
    if (avgPct > 100) level = 4;            // систематически выше лимита
    else if (avgPct >= 80) level = 3;       // подходит к лимиту
  } else {
    if (ulRatio != null && ulRatio > 1) level = 4;
    else if (ulRatio != null && ulRatio >= 0.8) level = 3;
    else if (avgPct < 85 && daysBelow >= 3) level = 2;
    else if (avgPct < 85) level = 1;
  }


  if (isLimitType) {
    BULLETS.push({
      label: t['Нутриент'],
      unit: t['Единица'],
      value: dailyValues[dailyValues.length - 1],
      limit: ul,
      avgPct,
      avgAbs,
      level,
      lastDayPct
    });
  } else {
    categories.forEach(cat => {
      if (!CATEGORY_SCORES[cat]) CATEGORY_SCORES[cat] = [];
      CATEGORY_SCORES[cat].push(Math.min(avgPct, 100));
      if (!CATEGORY_DETAILS[cat]) CATEGORY_DETAILS[cat] = [];
      CATEGORY_DETAILS[cat].push({ label: t['Нутриент'], pct: avgPct });
    });
  }

  const metricEntry = { label: t['Нутриент'], values: dailyPct, avgPct,
    upperBoundPct: (upperBoundPct && ulAppliesToDiet) ? upperBoundPct : null, isExcess: isLimitType,
    unit: t['Единица'] || '', avgAbs, rda, ul: ulEffective, ulRatio: ulRatioR, ulNote, level, lastDayPct,
    note: t['Примечание'] || null };
  const dailyTarget = isLimitType ? ul : rda;

  if (deviates) {
    HEAT_METRICS.push(metricEntry);
    SOURCES[t['Нутриент']] = {
      isExcess: isLimitType,
      dayPct: dailyPct, // % от нормы за каждый день — чтобы шторка знала факт по конкретному дню, а не гадала
      byDay: dayRows.map(r => topSourcesForDay(col, r['Date'].slice(0, 10), dailyTarget))
    };
  } else if (!isLimitType) {
    NORMAL_METRICS.push({ label: t['Нутриент'], avg: avgPct,
      unit: t['Единица'] || '', avgAbs, rda, ul: ulEffective, ulRatio: ulRatioR, ulNote, level });
  }

  if (isLimitType && !SOURCES[t['Нутриент']]) {
    SOURCES[t['Нутриент']] = {
      isExcess: true,
      dayPct: dailyPct,
      byDay: dayRows.map(r => topSourcesForDay(col, r['Date'].slice(0, 10), dailyTarget))
    };
  }
});

const scores = Object.entries(CATEGORY_SCORES).map(([label, arr]) => ({
  label,
  pct: Math.round(arr.reduce((a, b) => a + b, 0) / arr.length),
  // Топ-4 нутриента категории по вкладу (для карточки с разбивкой) — не все подряд,
  // чтобы карточка не расползалась, если в категории окажется много нутриентов
  nutrients: (CATEGORY_DETAILS[label] || []).sort((a, b) => b.pct - a.pct).slice(0, 4)
}));


// ===== Качество рациона: AHEI-2010 / NOVA / Plant Diversity (Chiuve 2012, пороги сверены) =====
function computeDietQuality(dayRows, weekMeals, toNum, opts) {
  opts = opts || {};
  const MALE = opts.male !== false;

  // --- конфиг (приближения, документированы; вынести в лист при желании тюнить) ---
  const SRV = { veg_g: 80, fruit_g: 100, legnut_g: 50, redmeat_g: 100, ssb_ml: 240, drink_g: 14 };
  // AHEI-2010: [значение → 0 баллов, значение → 10 баллов]
  const A = {
    veg:        [0, 5],        // порций/сут
    fruit:      [0, 4],        // порций/сут
    wholegrain: [0, MALE ? 90 : 75], // г/сут
    ssb:        [1, 0],        // порций/сут (обратная)
    legnut:     [0, 1],        // порций/сут
    redmeat:    [1.5, 0],      // порций/сут (обратная)
    transfat:   [4, 0.5],      // % энергии (обратная)
    epadha:     [0, 250],      // мг/сут
    pufa:       [2, 10],       // % энергии
    sodium:     [3020, 1130],  // мг/2000ккал (обратная; приближение децилей Chiuve)
  };
  const lin = (v, lo, hi) => {
    if (hi === lo) return v >= hi ? 10 : 0;
    const s = ((v - lo) / (hi - lo)) * 10;
    return Math.max(0, Math.min(10, s));
  };
  const alcoholPts = (drinks) => {
    if (MALE) {
      if (drinks <= 0) return 2.5;
      if (drinks < 0.5) return 2.5 + (drinks / 0.5) * 7.5;
      if (drinks <= 2.0) return 10;
      if (drinks < 3.5) return 10 - ((drinks - 2.0) / 1.5) * 10;
      return 0;
    }
    if (drinks <= 0) return 2.5;
    if (drinks < 0.5) return 2.5 + (drinks / 0.5) * 7.5;
    if (drinks <= 1.5) return 10;
    if (drinks < 2.5) return 10 - ((drinks - 1.5) / 1.0) * 10;
    return 0;
  };

  const dayList = dayRows.map(r => {
    const ds = String(r['Date']).slice(0, 10);
    const meals = weekMeals.filter(m => String(m['Date']).slice(0, 10) === ds);
    const total = meals.length;
    const tagged = meals.filter(m => String(m['NOVA'] || '').trim() !== '').length;
    const sum = k => meals.reduce((a, m) => a + toNum(m[k]), 0);
    const kcal = sum('Calories') || 1;

    const c = {
      veg:        lin(sum('veg_g') / SRV.veg_g, A.veg[0], A.veg[1]),
      fruit:      lin(sum('fruit_g') / SRV.fruit_g, A.fruit[0], A.fruit[1]),
      wholegrain: lin(sum('wholegrain_g'), A.wholegrain[0], A.wholegrain[1]),
      ssb:        lin(sum('ssb_ml') / SRV.ssb_ml, A.ssb[0], A.ssb[1]),
      legnut:     lin(sum('legume_nut_g') / SRV.legnut_g, A.legnut[0], A.legnut[1]),
      redmeat:    lin(sum('redmeat_g') / SRV.redmeat_g, A.redmeat[0], A.redmeat[1]),
      transfat:   lin(sum('Трансжиры') * 9 / kcal * 100, A.transfat[0], A.transfat[1]),
      epadha:     lin(sum('Омега-3 (EPA/DHA)'), A.epadha[0], A.epadha[1]),
      pufa:       lin(sum('ПНЖ') * 9 / kcal * 100, A.pufa[0], A.pufa[1]),
      sodium:     lin(sum('Натрий') * 2000 / kcal, A.sodium[0], A.sodium[1]),
      alcohol:    alcoholPts(sum('Алкоголь') / SRV.drink_g),
    };
    const ahei = Object.values(c).reduce((a, b) => a + b, 0); // 0..110

    const nova = { 1: 0, 2: 0, 3: 0, 4: 0 };
    meals.forEach(m => { const g = Math.max(1, Math.min(4, Math.round(toNum(m['NOVA']) || 1))); nova[g] += toNum(m['Calories']); });

    return { date: ds, ahei: Math.round(ahei * 10) / 10, components: c, kcal, total, tagged, nova };
  });

  // дни с достаточной разметкой (≥60% приёмов) и хоть какой-то едой
  const valid = dayList.filter(d => d.total > 0 && d.tagged / d.total >= 0.6);

  const aheiWeek = valid.length ? Math.round(valid.reduce((a, d) => a + d.ahei, 0) / valid.length) : null;
  const compWeek = {};
  if (valid.length) {
    Object.keys(A).concat('alcohol').forEach(k => {
      compWeek[k] = Math.round((valid.reduce((a, d) => a + d.components[k], 0) / valid.length) * 10) / 10;
    });
  }

  const novaCal = { 1: 0, 2: 0, 3: 0, 4: 0 }; let novaTot = 0;
  valid.forEach(d => { [1, 2, 3, 4].forEach(g => novaCal[g] += d.nova[g]); novaTot += d.kcal; });
  const novaPct = {};
  [1, 2, 3, 4].forEach(g => novaPct[g] = novaTot ? Math.round(novaCal[g] / novaTot * 100) : 0);

  // Plant Diversity — уникальные виды растений за окно.
  // Нормализация: lower, ё→е, снять прилагательные-уточнения, синонимы, грубый стем.
  const ADJ = /^(болгарск\w*|репчат\w*|зелен\w*|красн\w*|бел\w*|бело\w*|чёрн\w*|черн\w*|свеж\w*|сушен\w*|суш[её]н\w*|морожен\w*|отварн\w*|варен\w*|жарен\w*|печён\w*|печен\w*|цельнозернов\w*|стручков\w*|листов\w*|молот\w*|молодо\w*|крупнолистов\w*)\s+/;
  const SYN = { 'горошек': 'горох', 'айсберг': 'салат', 'руккола': 'салат', 'латук': 'салат', 'кинза': 'кориандр', 'коф': 'кофе', 'кориц': 'корица', 'какао': 'какао', 'томатная паста': 'томат', 'помидор': 'томат', 'черри': 'томат', 'семечки': 'семена', 'семя': 'семена' };
  const norm = s => {
    let x = s.trim().toLowerCase().replace(/ё/g, 'е').replace(/[.()]/g, '').trim();
    x = x.replace(ADJ, '').trim();
    const w = x.split(/\s+/);
    x = w[0]; // первое слово ("капуста белокочанная"→"капуста", "лук репчатый"→"лук")
    x = x.replace(/(ый|ая|ое|ые|ой|ую|ого|ым|ов|ами|ам|ах|а|ы|и|у|е|я|й)$/, '');
    return SYN[x] || SYN[s.trim().toLowerCase()] || x;
  };
  const NOT_PLANT = new Set(['чук', 'нор', 'вода', 'бульон', 'молок', 'сыр', 'йогурт', 'творог', 'масл', 'мед', 'соус',
    'куриц', 'курин', 'говядин', 'свинин', 'индейк', 'индюш', 'лосос', 'рыб', 'яйц', 'креветк', 'тунец', 'сельд', 'треск', 'мясо', 'бекон', 'колбас', 'ветчин', 'сосиск', 'печен', 'желатин', 'дрожж', 'злак',
    // осколки прилагательных, которые LLM иногда отдаёт отдельной запятой
    'болгарск', 'зелен', 'красн', 'бел', 'черн', 'свеж', 'сушен', 'молот', 'репчат', 'отварн', 'печ', 'жарен', 'варен', 'цельнозернов', 'водоросл']);
  const SYN2 = { 'карр': 'карри', 'кабач': 'кабачок', 'помидорчик': 'томат', 'горош': 'горох' };
  const plantSet = new Set();
  weekMeals.forEach(m => String(m['plants'] || '').split(/[,;/]+/).map(norm)
    .map(p => SYN2[p] || p)
    .filter(p => p.length >= 3 && !NOT_PLANT.has(p)).forEach(p => plantSet.add(p)));

  const daysWithFood = dayList.filter(d => d.total > 0).length;

  return {
    ahei: {
      week_avg: aheiWeek, target: 80, ok: 65, max: 110,
      days: dayList.map(d => ({ date: d.date, score: d.tagged / (d.total || 1) >= 0.6 ? d.ahei : null })),
      components: compWeek,
      coverage: valid.length + '/' + daysWithFood,
    },
    nova: { pct: novaPct, ultra_pct: novaPct[4], whole_pct: novaPct[1] },
    plants: { count: plantSet.size, target: 30, list: [...plantSet].sort() },
    computed_days: valid.length,
  };
}
let dietQuality = null;
try { dietQuality = computeDietQuality(dayRows, weekMeals, toNum, { male: true }); } catch (e) { dietQuality = { error: String(e && e.message || e) }; }

const finalResult = {
  period: {
    from: dayRows[0] ? dayRows[0]['Date'] : null,
    to: dayRows[dayRows.length - 1] ? dayRows[dayRows.length - 1]['Date'] : null
  },
  days: dayRows.map(r => r['Date']),
  scores,
  bullets: BULLETS,
  heatmap: HEAT_METRICS,
  diet_quality: dietQuality,
  normal: NORMAL_METRICS,
  sources: SOURCES,
  computed_at: new Date().toISOString()
};

// Пишем в Static Data workflow'а — переживает между запусками, без файловой системы.
// Причина такого решения: n8n по умолчанию блокирует запись файлов внутрь папки .n8n
// (N8N_BLOCK_FILE_ACCESS_TO_N8N_FILES), а другого примонтированного пути на сервере нет.
const staticData = $getWorkflowStaticData('global');
staticData.weeklyNutrients = finalResult;

return [ { json: finalResult } ];

const __t = ($input.first().json.query || {}).token;
if (__t !== '8j1bXp92BF5VabxNq2VN') return [{ json: { error: 'forbidden' } }];
// Нода подключена напрямую к Webhook в той же workflow, что и Schedule Trigger-ветка.
// Static Data общая на весь workflow, поэтому здесь доступны данные,
// записанные веткой с Schedule Trigger.

const staticData = $getWorkflowStaticData('global');
const cached = staticData.weeklyNutrients;

if (!cached) {
  // Кэш ещё ни разу не считался (например, сразу после создания workflow) —
  // отдаём понятную заглушку вместо ошибки.
  return [{
    json: {
      error: 'no_data_yet',
      message: 'Данные ещё не посчитаны. Дождитесь первого запуска по расписанию.'
    }
  }];
}

return [{ json: cached }];

// Нода подключена к прямому выходу "Get Meals" (последняя в цепочке Schedule Trigger).
// Ссылается на "Get day_sum" и "Get Nutrient_Targets" по имени — обе идут раньше в цепочке:
// Schedule Trigger → Get day_sum → Get Nutrient_Targets → Get Meals → Code

// Достаёт первое число из строки-ячейки. Возвращает null, если значение
// начинается с "не " (не установлен / не применимо / не задана) — иначе
// регэксп нашёл бы случайное число из справочного текста в скобках.
function parseNum(v) {
  if (v === undefined || v === null) return null;
  const s = String(v).trim();
  if (/^не\s/i.test(s)) return null;
  const m = s.match(/-?\d+(?:[.,]\d+)?/);
  if (!m) return null;
  return parseFloat(m[0].replace(',', '.'));
}

function toNum(v) {
  if (v === undefined || v === null || v === '') return 0;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace(',', '.'));
  return isNaN(n) ? 0 : n;
}

// 1. Дни за неделю — обращаемся к "Get day_sum" по имени.
// ВАЖНО: в отличие от wellness-домена (Daily_Trends, колонка 'Дата', кириллица),
// у day_sum дата хранится в колонке 'Date' (латиница) — известная особенность проекта.
const dayRows = $('Get day_sum').all()
  .map(r => r.json)
  .filter(r => r['Date'])
  .sort((a, b) => (a['Date'] < b['Date']) ? 1 : (a['Date'] > b['Date']) ? -1 : 0)
  .slice(0, 7)
  .reverse(); // от старых к новым

const weekDateSet = new Set(dayRows.map(r => r['Date'].slice(0, 10))); // YYYY-MM-DD

// 2. Справочник целей — обращаемся к "Get Nutrient_Targets" по имени
const targets = $('Get Nutrient_Targets').all().map(r => r.json);

// 3. Сырые приёмы пищи за ту же неделю — прямой вход этой ноды (Get Meals)
const weekMeals = $input.all()
  .map(r => r.json)
  .filter(r => r['Date'] && weekDateSet.has(String(r['Date']).slice(0, 10)));

// Топ-3 продукта-источника нутриента ЗА КОНКРЕТНЫЙ ДЕНЬ (не за неделю), сгруппированные
// по описанию блюда. % считается от ДНЕВНОЙ нормы/лимита — так сумма топ-3 напрямую
// объясняет цифру в самой ячейке heatmap за этот день, а не абстрактную "долю от недели".
function topSourcesForDay(col, dateStr, dailyTarget) {
  if (!dailyTarget) return [];
  const dayMeals = weekMeals.filter(m => String(m['Date']).slice(0, 10) === dateStr);
  const byName = {};
  dayMeals.forEach(m => {
    const v = toNum(m[col]);
    if (v <= 0) return;
    const name = m['Meal_description'] || 'Без описания';
    byName[name] = (byName[name] || 0) + v;
  });
  return Object.entries(byName)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 3)
    .map(([name, val]) => ({ name, pct: Math.round((val / dailyTarget) * 100) }));
}

const HEAT_METRICS = [];
const NORMAL_METRICS = [];
const CATEGORY_SCORES = {}; // { "Здоровье костей": [pct, pct, ...] }
const CATEGORY_DETAILS = {}; // { "Здоровье костей": [{label, pct}, ...] } — для карточек с разбивкой
const BULLETS = [];
const SOURCES = {}; // { "Витамин D": [{name, pct}, ...] }

targets.forEach(t => {
  const col = t['Колонка_в_Meals'];
  if (!col) return;

  const rda = parseNum(t['Норма_RDA_AI']);
  const ul = parseNum(t['Верхний_предел_UL']);
  const categories = (t['Категория'] || '').split(';').map(c => c.trim()).filter(Boolean);
  const isLimitType = categories.includes('Риск избытка');

  // UL некоторых нутриентов (магний и т.п.) относится ТОЛЬКО к добавкам, не к пище —
  // см. поле Примечание в справочнике. Такой UL не применяем к дневному рациону.
  const ulAppliesToDiet = !/добав/i.test(String(t['Верхний_предел_UL'] || ''));

  const dailyValues = dayRows.map(r => toNum(r[col]));
  const dailyPct = dailyValues.map(v => {
    if (isLimitType) return ul ? Math.round((v / ul) * 100) : null;
    return rda ? Math.round((v / rda) * 100) : null;
  }).filter(p => p !== null);

  if (dailyPct.length === 0) return; // нет ни цели, ни UL — пропускаем

  const avgPct = Math.round(dailyPct.reduce((a, b) => a + b, 0) / dailyPct.length);

  // Показываем в heatmap только ГЕНУИННЫЕ недельные паттерны, не разовые всплески дня:
  // - дефицит — если недельное СРЕДНЕЕ ниже нормы (не просто один плохой день)
  // - избыток — только для goal-type нутриентов (магний, витамин D и т.п.), и только если
  //   минимум 2 дня подряд/за неделю реально вышли за порог (один разовый приём — не система)
  // Risk-type нутриенты (натрий, сахар и т.п.) в heatmap не попадают вообще — они и так
  // всегда видны в "Риск избытка", дублировать их здесь — просто шум.
  const upperBoundPct = (ul && rda) ? Math.round((ul / rda) * 100) : null;
  const daysOverThreshold = (upperBoundPct && ulAppliesToDiet)
    ? dailyPct.filter(p => p > upperBoundPct).length
    : 0;
  const deviates = !isLimitType && (avgPct < 85 || daysOverThreshold >= 2);

  // --- Фаза 6: абсолютные величины, расстояние до верхнего предела, уровень сигнала ---
  // Процент без базы и единиц не интерпретируем, поэтому отдаём и абсолюты, и UL.
  const avgAbs = dailyValues.length
    ? Math.round((dailyValues.reduce((a, b) => a + b, 0) / dailyValues.length) * 100) / 100
    : null;
  const ulEffective = (ul && ulAppliesToDiet) ? ul : null;
  const ulRatio = (ulEffective && avgAbs != null && ulEffective > 0) ? avgAbs / ulEffective : null;
  const ulRatioR = ulRatio != null ? Math.round(ulRatio * 100) / 100 : null;
  const ulNote = (ul && !ulAppliesToDiet) ? 'верхний предел относится только к добавкам, не к пище' : null;
  const daysBelow = dailyPct.filter(p => p < 85).length;

  // Лестница сигналов: 0 норма · 1 дефицит · 2 устойчивый дефицит · 3 подход к пределу · 4 выше предела
  // Важно: дефицит определяется по НЕДЕЛЬНОМУ среднему. Отдельные «плохие» дни есть
  // у любого нутриента (обычные колебания) и сами по себе сигналом не являются —
  // они лишь усиливают уже подтверждённый средним дефицит до «устойчивого».
  const lastDayPct = dailyPct.length ? dailyPct[dailyPct.length - 1] : null;
  let level = 0;
  if (isLimitType) {
    if (avgPct > 100) level = 4;            // систематически выше лимита
    else if (avgPct >= 80) level = 3;       // подходит к лимиту
  } else {
    if (ulRatio != null && ulRatio > 1) level = 4;
    else if (ulRatio != null && ulRatio >= 0.8) level = 3;
    else if (avgPct < 85 && daysBelow >= 3) level = 2;
    else if (avgPct < 85) level = 1;
  }


  if (isLimitType) {
    BULLETS.push({
      label: t['Нутриент'],
      unit: t['Единица'],
      value: dailyValues[dailyValues.length - 1],
      limit: ul,
      avgPct,
      avgAbs,
      level,
      lastDayPct
    });
  } else {
    categories.forEach(cat => {
      if (!CATEGORY_SCORES[cat]) CATEGORY_SCORES[cat] = [];
      CATEGORY_SCORES[cat].push(Math.min(avgPct, 100));
      if (!CATEGORY_DETAILS[cat]) CATEGORY_DETAILS[cat] = [];
      CATEGORY_DETAILS[cat].push({ label: t['Нутриент'], pct: avgPct });
    });
  }

  const metricEntry = { label: t['Нутриент'], values: dailyPct, avgPct,
    upperBoundPct: (upperBoundPct && ulAppliesToDiet) ? upperBoundPct : null, isExcess: isLimitType,
    unit: t['Единица'] || '', avgAbs, rda, ul: ulEffective, ulRatio: ulRatioR, ulNote, level, lastDayPct,
    note: t['Примечание'] || null };
  const dailyTarget = isLimitType ? ul : rda;

  if (deviates) {
    HEAT_METRICS.push(metricEntry);
    SOURCES[t['Нутриент']] = {
      isExcess: isLimitType,
      dayPct: dailyPct, // % от нормы за каждый день — чтобы шторка знала факт по конкретному дню, а не гадала
      byDay: dayRows.map(r => topSourcesForDay(col, r['Date'].slice(0, 10), dailyTarget))
    };
  } else if (!isLimitType) {
    NORMAL_METRICS.push({ label: t['Нутриент'], avg: avgPct,
      unit: t['Единица'] || '', avgAbs, rda, ul: ulEffective, ulRatio: ulRatioR, ulNote, level });
  }

  if (isLimitType && !SOURCES[t['Нутриент']]) {
    SOURCES[t['Нутриент']] = {
      isExcess: true,
      dayPct: dailyPct,
      byDay: dayRows.map(r => topSourcesForDay(col, r['Date'].slice(0, 10), dailyTarget))
    };
  }
});

const scores = Object.entries(CATEGORY_SCORES).map(([label, arr]) => ({
  label,
  pct: Math.round(arr.reduce((a, b) => a + b, 0) / arr.length),
  // Топ-4 нутриента категории по вкладу (для карточки с разбивкой) — не все подряд,
  // чтобы карточка не расползалась, если в категории окажется много нутриентов
  nutrients: (CATEGORY_DETAILS[label] || []).sort((a, b) => b.pct - a.pct).slice(0, 4)
}));


// ===== Качество рациона: AHEI-2010 / NOVA / Plant Diversity (Chiuve 2012, пороги сверены) =====
function computeDietQuality(dayRows, weekMeals, toNum, opts) {
  opts = opts || {};
  const MALE = opts.male !== false;

  // --- конфиг (приближения, документированы; вынести в лист при желании тюнить) ---
  const SRV = { veg_g: 80, fruit_g: 100, legnut_g: 50, redmeat_g: 100, ssb_ml: 240, drink_g: 14 };
  // AHEI-2010: [значение → 0 баллов, значение → 10 баллов]
  const A = {
    veg:        [0, 5],        // порций/сут
    fruit:      [0, 4],        // порций/сут
    wholegrain: [0, MALE ? 90 : 75], // г/сут
    ssb:        [1, 0],        // порций/сут (обратная)
    legnut:     [0, 1],        // порций/сут
    redmeat:    [1.5, 0],      // порций/сут (обратная)
    transfat:   [4, 0.5],      // % энергии (обратная)
    epadha:     [0, 250],      // мг/сут
    pufa:       [2, 10],       // % энергии
    sodium:     [3020, 1130],  // мг/2000ккал (обратная; приближение децилей Chiuve)
  };
  const lin = (v, lo, hi) => {
    if (hi === lo) return v >= hi ? 10 : 0;
    const s = ((v - lo) / (hi - lo)) * 10;
    return Math.max(0, Math.min(10, s));
  };
  const alcoholPts = (drinks) => {
    if (MALE) {
      if (drinks <= 0) return 2.5;
      if (drinks < 0.5) return 2.5 + (drinks / 0.5) * 7.5;
      if (drinks <= 2.0) return 10;
      if (drinks < 3.5) return 10 - ((drinks - 2.0) / 1.5) * 10;
      return 0;
    }
    if (drinks <= 0) return 2.5;
    if (drinks < 0.5) return 2.5 + (drinks / 0.5) * 7.5;
    if (drinks <= 1.5) return 10;
    if (drinks < 2.5) return 10 - ((drinks - 1.5) / 1.0) * 10;
    return 0;
  };

  const dayList = dayRows.map(r => {
    const ds = String(r['Date']).slice(0, 10);
    const meals = weekMeals.filter(m => String(m['Date']).slice(0, 10) === ds);
    const total = meals.length;
    const tagged = meals.filter(m => String(m['NOVA'] || '').trim() !== '').length;
    const sum = k => meals.reduce((a, m) => a + toNum(m[k]), 0);
    const kcal = sum('Calories') || 1;

    const c = {
      veg:        lin(sum('veg_g') / SRV.veg_g, A.veg[0], A.veg[1]),
      fruit:      lin(sum('fruit_g') / SRV.fruit_g, A.fruit[0], A.fruit[1]),
      wholegrain: lin(sum('wholegrain_g'), A.wholegrain[0], A.wholegrain[1]),
      ssb:        lin(sum('ssb_ml') / SRV.ssb_ml, A.ssb[0], A.ssb[1]),
      legnut:     lin(sum('legume_nut_g') / SRV.legnut_g, A.legnut[0], A.legnut[1]),
      redmeat:    lin(sum('redmeat_g') / SRV.redmeat_g, A.redmeat[0], A.redmeat[1]),
      transfat:   lin(sum('Трансжиры') * 9 / kcal * 100, A.transfat[0], A.transfat[1]),
      epadha:     lin(sum('Омега-3 (EPA/DHA)'), A.epadha[0], A.epadha[1]),
      pufa:       lin(sum('ПНЖ') * 9 / kcal * 100, A.pufa[0], A.pufa[1]),
      sodium:     lin(sum('Натрий') * 2000 / kcal, A.sodium[0], A.sodium[1]),
      alcohol:    alcoholPts(sum('Алкоголь') / SRV.drink_g),
    };
    const ahei = Object.values(c).reduce((a, b) => a + b, 0); // 0..110

    const nova = { 1: 0, 2: 0, 3: 0, 4: 0 };
    meals.forEach(m => { const g = Math.max(1, Math.min(4, Math.round(toNum(m['NOVA']) || 1))); nova[g] += toNum(m['Calories']); });

    return { date: ds, ahei: Math.round(ahei * 10) / 10, components: c, kcal, total, tagged, nova };
  });

  // дни с достаточной разметкой (≥60% приёмов) и хоть какой-то едой
  const valid = dayList.filter(d => d.total > 0 && d.tagged / d.total >= 0.6);

  const aheiWeek = valid.length ? Math.round(valid.reduce((a, d) => a + d.ahei, 0) / valid.length) : null;
  const compWeek = {};
  if (valid.length) {
    Object.keys(A).concat('alcohol').forEach(k => {
      compWeek[k] = Math.round((valid.reduce((a, d) => a + d.components[k], 0) / valid.length) * 10) / 10;
    });
  }

  const novaCal = { 1: 0, 2: 0, 3: 0, 4: 0 }; let novaTot = 0;
  valid.forEach(d => { [1, 2, 3, 4].forEach(g => novaCal[g] += d.nova[g]); novaTot += d.kcal; });
  const novaPct = {};
  [1, 2, 3, 4].forEach(g => novaPct[g] = novaTot ? Math.round(novaCal[g] / novaTot * 100) : 0);

  // Plant Diversity — уникальные виды растений за окно.
  // Нормализация: lower, ё→е, снять прилагательные-уточнения, синонимы, грубый стем.
  const ADJ = /^(болгарск\w*|репчат\w*|зелен\w*|красн\w*|бел\w*|бело\w*|чёрн\w*|черн\w*|свеж\w*|сушен\w*|суш[её]н\w*|морожен\w*|отварн\w*|варен\w*|жарен\w*|печён\w*|печен\w*|цельнозернов\w*|стручков\w*|листов\w*|молот\w*|молодо\w*|крупнолистов\w*)\s+/;
  const SYN = { 'горошек': 'горох', 'айсберг': 'салат', 'руккола': 'салат', 'латук': 'салат', 'кинза': 'кориандр', 'коф': 'кофе', 'кориц': 'корица', 'какао': 'какао', 'томатная паста': 'томат', 'помидор': 'томат', 'черри': 'томат', 'семечки': 'семена', 'семя': 'семена' };
  const norm = s => {
    let x = s.trim().toLowerCase().replace(/ё/g, 'е').replace(/[.()]/g, '').trim();
    x = x.replace(ADJ, '').trim();
    const w = x.split(/\s+/);
    x = w[0]; // первое слово ("капуста белокочанная"→"капуста", "лук репчатый"→"лук")
    x = x.replace(/(ый|ая|ое|ые|ой|ую|ого|ым|ов|ами|ам|ах|а|ы|и|у|е|я|й)$/, '');
    return SYN[x] || SYN[s.trim().toLowerCase()] || x;
  };
  const NOT_PLANT = new Set(['чук', 'нор', 'вода', 'бульон', 'молок', 'сыр', 'йогурт', 'творог', 'масл', 'мед', 'соус',
    'куриц', 'курин', 'говядин', 'свинин', 'индейк', 'индюш', 'лосос', 'рыб', 'яйц', 'креветк', 'тунец', 'сельд', 'треск', 'мясо', 'бекон', 'колбас', 'ветчин', 'сосиск', 'печен', 'желатин', 'дрожж', 'злак',
    // осколки прилагательных, которые LLM иногда отдаёт отдельной запятой
    'болгарск', 'зелен', 'красн', 'бел', 'черн', 'свеж', 'сушен', 'молот', 'репчат', 'отварн', 'печ', 'жарен', 'варен', 'цельнозернов', 'водоросл']);
  const SYN2 = { 'карр': 'карри', 'кабач': 'кабачок', 'помидорчик': 'томат', 'горош': 'горох' };
  const plantSet = new Set();
  weekMeals.forEach(m => String(m['plants'] || '').split(/[,;/]+/).map(norm)
    .map(p => SYN2[p] || p)
    .filter(p => p.length >= 3 && !NOT_PLANT.has(p)).forEach(p => plantSet.add(p)));

  const daysWithFood = dayList.filter(d => d.total > 0).length;

  return {
    ahei: {
      week_avg: aheiWeek, target: 80, ok: 65, max: 110,
      days: dayList.map(d => ({ date: d.date, score: d.tagged / (d.total || 1) >= 0.6 ? d.ahei : null })),
      components: compWeek,
      coverage: valid.length + '/' + daysWithFood,
    },
    nova: { pct: novaPct, ultra_pct: novaPct[4], whole_pct: novaPct[1] },
    plants: { count: plantSet.size, target: 30, list: [...plantSet].sort() },
    computed_days: valid.length,
  };
}
let dietQuality = null;
try { dietQuality = computeDietQuality(dayRows, weekMeals, toNum, { male: true }); } catch (e) { dietQuality = { error: String(e && e.message || e) }; }

const finalResult = {
  period: {
    from: dayRows[0] ? dayRows[0]['Date'] : null,
    to: dayRows[dayRows.length - 1] ? dayRows[dayRows.length - 1]['Date'] : null
  },
  days: dayRows.map(r => r['Date']),
  scores,
  bullets: BULLETS,
  heatmap: HEAT_METRICS,
  diet_quality: dietQuality,
  normal: NORMAL_METRICS,
  sources: SOURCES,
  computed_at: new Date().toISOString()
};

// Пишем в Static Data workflow'а — переживает между запусками, без файловой системы.
// Причина такого решения: n8n по умолчанию блокирует запись файлов внутрь папки .n8n
// (N8N_BLOCK_FILE_ACCESS_TO_N8N_FILES), а другого примонтированного пути на сервере нет.
const staticData = $getWorkflowStaticData('global');
staticData.weeklyNutrients = finalResult;

return [ { json: finalResult } ];
